// ============================================================
// CONFIGURACIÓN DE LA FÁBRICA AUTÓNOMA
// Blogs activos con cuota de artículos por semana
// ============================================================

const BLOGS_ACTIVOS = [
  // === ANIMALES (Hotmart) ===
  { id: '6910813708926842116', nombre: 'Alimentación para perros',  nicho: 'animales', articulos_semana: 3, productos: ['dieta-natural','snack-barf','vital-pet'] },
  { id: '6617865557052467517', nombre: 'Alimentación para gatos',   nicho: 'animales', articulos_semana: 2, productos: ['entiende-gato','dieta-natural','mascotas-sanas'] },
