  { id: '2171262240069038424', nombre: 'Hurones',                   nicho: 'animales', articulos_semana: 1, productos: ['mascotas-sanas'] },
  { id: '6959662622118866680', nombre: 'Vet bovinos',               nicho: 'animales', articulos_semana: 1, productos: ['mascotas-sanas'] },
  // === LEYES (AdSense + Leads) ===
  { id: '4185821469969358370', nombre: 'Abogados bienes raíces USA',    nicho: 'leyes', articulos_semana: 2, productos: [] },
  { id: '6030388327366455376', nombre: 'Abogados accidente Orlando',    nicho: 'leyes', articulos_semana: 2, productos: [] },
  { id: '3503300865393838043', nombre: 'Abogados familia USA',          nicho: 'leyes', articulos_semana: 2, productos: [] },
  { id: '3388695765945711848', nombre: 'Litigios USA',                  nicho: 'leyes', articulos_semana: 1, productos: [] }
];

const PRODUCTOS_HOTMART = {
  'dieta-natural':   { nombre: 'Dieta Natural para Perros y Gatos',   link: 'https://go.hotmart.com/X103617747C',      imagen: 'https://static-media.hotmart.com/KNdDfZogqE2CWDv4nqEsswzDFjc=/300x300/filters:quality(100)/hotmart/product_pictures/ecbf6914-08bb-4682-aa5b-1990b80b5afb/postinstagrampatitas.png',  tipo: 'Guía',       color: { grad: '135deg,#1a7a4a,#2ecc71', text: '#1a7a4a', bg: '#eafaf1' } },
  'snack-barf':      { nombre: 'Snack BARF en Minutos',               link: 'https://go.hotmart.com/R103617833Q',      imagen: 'https://static-media.hotmart.com/XusqQYSq_oAB8-EO0Iwr3xVnPMk=/300x300/smart/filters:format(webp):background_color(white)/hotmart/product_pictures/aaef333c-c030-4c46-a0e7-0c1b780837fe/snackbarf600x600.png?w=920', tipo: 'Recetas',    color: { grad: '135deg,#1a7a4a,#27ae60', text: '#1a7a4a', bg: '#eafaf1' } },
  'adiestramiento':  { nombre: 'Adiestramiento Canino Profesional',   link: 'https://go.hotmart.com/D104257979A',      imagen: 'https://hotmart.s3.amazonaws.com/product_pictures/141a3c3d-a535-40f5-99e1-a275199b7e98/Portadahotmart5.png',                                                                                                             tipo: 'Curso',      color: { grad: '135deg,#1a5276,#2980b9', text: '#1a5276', bg: '#eaf4fb' } },
  'entiende-gato':   { nombre: 'Entiende a tu Gato: Guía Práctica',  link: 'https://go.hotmart.com/F104226854F',      imagen: 'https://d1yei2z3i6k35z.cloudfront.net/11998843/683bb259ca94a_CopiadeSint%C3%ADtulo1.png',                                                                                                                          tipo: 'Guía',       color: { grad: '135deg,#6c3483,#a569bd', text: '#6c3483', bg: '#f9f0ff' } },
  'mascotas-sanas':  { nombre: 'Mascotas Sanas',                      link: 'https://go.hotmart.com/L104257678P?dp=1', imagen: 'https://static-media.hotmart.com/9H3NJb3S4H61OsufTjZpXLy-8KY=/300x300/smart/filters:format(webp):background_color(white)/hotmart/product_pictures/78592f13-96f1-4724-9b6a-2640aadcf606/MasterSello20211116T162945331.jpg?w=920', tipo: 'Curso',      color: { grad: '135deg,#1a5276,#2980b9', text: '#1a5276', bg: '#eaf4fb' } },
  'vital-pet':       { nombre: 'Vital Pet System',                    link: 'https://go.hotmart.com/W104257847B',      imagen: 'https://static-media.hotmart.com/F3PzytJIAVCectZMFSnvMHJFV5g=/filters:background_color(white)/hotmart/product_pictures/a801721c-590d-4a30-ab01-5fe5eb532e8f/PORTADAVITALPET.png',                                                      tipo: 'Sistema',    color: { grad: '135deg,#1a7a4a,#27ae60', text: '#1a7a4a', bg: '#eafaf1' } },
  'calculadora':     { nombre: 'Calculadora de Alimentación Cocida',  link: 'https://go.hotmart.com/B104226750N',      imagen: 'https://static-media.hotmart.com/Gt9GpGBSzCdG8hfSbvKgGuXEhFY=/300x300/smart/filters:format(webp):background_color(white)/hotmart/product_pictures/5f151330-675e-4498-8764-1fba21c4b505/Calculadoradealimentacioncocidaparaperrosygatos.png?w=920', tipo: 'Herramienta', color: { grad: '135deg,#1a7a4a,#27ae60', text: '#1a7a4a', bg: '#eafaf1' } }
};

const ADSENSE_PUBLISHER_ID = 'ca-pub-1913674678143092';

return BLOGS_ACTIVOS.map(blog => ({
  json: { blog, PRODUCTOS_HOTMART, ADSENSE_PUBLISHER_ID }
}));

const response = $input.item.json;
const config = $('Configuración Fábrica').item.json;
const { blog, PRODUCTOS_HOTMART } = config;

// Parsear respuesta de DeepSeek
let rawContent = response.choices?.[0]?.message?.content || '{"articulos":[]}';
// Limpiar markdown si DeepSeek lo incluye
rawContent = rawContent.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let ideas;
try {
  ideas = JSON.parse(rawContent);
} catch (e) {
  // Si el JSON está malformado, extraer con regex
  const match = rawContent.match(/\{.*\}/s);
  ideas = match ? JSON.parse(match[0]) : { articulos: [] };
}

const articulos = ideas.articulos || [];

// Seleccionar mejor producto para cada artículo (animales)
const KEYWORDS_PRODUCTO = {
  'dieta-natural':   ['dieta','alimentacion','comida','nutricion','natural','comer'],
  'snack-barf':      ['barf','snack','receta','premio','trato','crudo'],
  'adiestramiento':  ['adiestrar','adiestramiento','entrenamiento','conducta','obediencia','comando','ladrar','morder'],
  'entiende-gato':   ['gato','felino','comportamiento','maullar','ronronear','felinos'],
  'mascotas-sanas':  ['salud','sano','enfermedad','veterinario','vacuna','cuidado'],
  'vital-pet':       ['cocido','casero','natural','sistema','preparar'],
  'calculadora':     ['calculadora','porcion','cantidad','medida','cuanto']
};

return articulos.map(art => {
  let mejorProducto = blog.productos[0] || null;
  let mejorScore = 0;

  if (blog.nicho === 'animales' && blog.productos.length > 0) {
    const tituloLower = art.titulo.toLowerCase();
    for (const prodId of blog.productos) {
      const kws = KEYWORDS_PRODUCTO[prodId] || [];
      const score = kws.filter(kw => tituloLower.includes(kw)).length;
      if (score > mejorScore) { mejorScore = score; mejorProducto = prodId; }
    }
  }

  return {
    json: {
      blog,
      articulo: art,
      productoId: mejorProducto,
      PRODUCTOS_HOTMART,
      ADSENSE_PUBLISHER_ID: config.ADSENSE_PUBLISHER_ID
    }
  };
});

const response = $input.item.json;
const { blog, articulo, productoId, PRODUCTOS_HOTMART, ADSENSE_PUBLISHER_ID } = $('Parsear Ideas y Asignar Producto').item.json;

const contenidoIA = response.choices?.[0]?.message?.content || '';

// -------------------------------------------------------
// Insertar AdSense a mitad del contenido
// -------------------------------------------------------
const adsenseMid = `
<!-- ADSENSE MID-ARTICLE -->
<div style="margin:32px 0;text-align:center">
  <ins class="adsbygoogle"
       style="display:block"
       data-ad-client="${ADSENSE_PUBLISHER_ID}"
       data-ad-slot="SLOT_MID_ARTICLE"
       data-ad-format="auto"
       data-full-width-responsive="true"></ins>
  <script>(adsbygoogle = window.adsbygoogle || []).push({});</script>
</div>`;

const mitad = Math.floor(contenidoIA.length / 2);
const corte = contenidoIA.indexOf('</p>', mitad);
const punto = corte > 0 ? corte + 4 : mitad;
const contenidoConAds = contenidoIA.slice(0, punto) + adsenseMid + contenidoIA.slice(punto);

// -------------------------------------------------------
// Banner de monetización según nicho
// -------------------------------------------------------
let bannerFinal = '';

if (blog.nicho === 'animales' && productoId && PRODUCTOS_HOTMART[productoId]) {
  const prod = PRODUCTOS_HOTMART[productoId];
  const c = prod.color;
  bannerFinal = `
<!-- HOTMART BANNER -->
<div style="background:linear-gradient(${c.grad});border-radius:14px;padding:0;margin:40px 0;overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,.12);font-family:Arial,sans-serif;max-width:700px">
  <div style="display:flex;align-items:stretch;flex-wrap:wrap">
    <img src="${prod.imagen}" alt="${prod.nombre}" style="width:150px;height:auto;object-fit:cover;flex-shrink:0">
    <div style="flex:1;min-width:180px;padding:20px;display:flex;flex-direction:column;justify-content:center">
      <p style="color:rgba(255,255,255,.8);font-size:10px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;margin:0 0 5px">${prod.tipo} recomendado</p>
      <h3 style="color:#fff;font-size:17px;font-weight:800;margin:0 0 8px;line-height:1.3">${prod.nombre}</h3>
      <a href="${prod.link}" target="_blank" rel="noopener sponsored" style="display:inline-block;background:#fff;color:${c.text};font-weight:800;font-size:13px;padding:10px 20px;border-radius:8px;text-decoration:none;align-self:flex-start">Ver ahora →</a>
    </div>
  </div>
  <p style="color:rgba(255,255,255,.3);font-size:9px;text-align:right;padding:3px 12px;margin:0">*Enlace de afiliado</p>
</div>`;
} else if (blog.nicho === 'leyes') {
  bannerFinal = `
<!-- LEAD WIDGET LEYES -->
<div style="background:#f0f3f4;border:2px solid #2c3e50;border-radius:14px;padding:28px;margin:40px 0 0;font-family:Arial,sans-serif;max-width:700px">
  <h3 style="color:#2c3e50;font-size:20px;font-weight:800;margin:0 0 8px">¿Necesitas Asesoría Legal Gratuita? ⚖️</h3>
  <p style="color:#444;font-size:14px;margin:0 0 16px;line-height:1.6">Nuestros abogados especializados te orientan sin costo. <strong>Primera consulta gratuita y confidencial.</strong></p>
  <div style="display:flex;gap:10px;flex-wrap:wrap">
    <a href="tel:+18000000000" style="flex:1;min-width:160px;display:inline-block;background:#2c3e50;color:#fff;font-weight:800;font-size:14px;padding:13px 20px;border-radius:8px;text-decoration:none;text-align:center">📞 Llamar Gratis</a>
    <a href="https://wa.me/18000000000" target="_blank" rel="noopener" style="flex:1;min-width:160px;display:inline-block;background:#25d366;color:#fff;font-weight:800;font-size:14px;padding:13px 20px;border-radius:8px;text-decoration:none;text-align:center">💬 WhatsApp</a>
  </div>
  <p style="color:#aaa;font-size:11px;margin:12px 0 0">Confidencial · Sin compromiso · Respuesta en 24h</p>
</div>`;
}

// AdSense bottom
const adsenseBottom = `
<div style="margin:32px 0;text-align:center">
  <ins class="adsbygoogle"
       style="display:block"
       data-ad-client="${ADSENSE_PUBLISHER_ID}"
       data-ad-slot="SLOT_BOTTOM_ARTICLE"
       data-ad-format="auto"
       data-full-width-responsive="true"></ins>
  <script>(adsbygoogle = window.adsbygoogle || []).push({});</script>
</div>`;

const htmlFinal = contenidoConAds + bannerFinal + adsenseBottom;

return [{
  json: {
    blogId: blog.id,
    blogNombre: blog.nombre,
    blogNicho: blog.nicho,
    titulo: articulo.titulo,
    keyword: articulo.keyword_principal,
    productoUsado: productoId,
    labels: [blog.nicho, articulo.keyword_principal?.replace(/\s+/g,'-').toLowerCase()].filter(Boolean),
    contenido: htmlFinal
  }
}];

const response = $input.item.json;
let rawContent = response.choices?.[0]?.message?.content || '{"nichos":[]}';
rawContent = rawContent.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let data;
try { data = JSON.parse(rawContent); } catch(e) {
  const match = rawContent.match(/\{.*\}/s);
  data = match ? JSON.parse(match[0]) : { nichos: [] };
}

return [{ json: { nichos: data.nichos || [], generadoEn: new Date().toISOString() } }];

// Consolidar resultados de la semana
const nichos = $('Parsear Análisis de Nichos').item.json.nichos || [];

const topNichos = nichos.slice(0, 5).map((n, i) =>
  `${i+1}. <b>${n.nombre}</b> (${n.tipo}) — CPC ~$${n.cpc_estimado_usd} | Competencia: ${n.competencia} | ${n.razon}`
).join('<br>');

const articulosIdeas = nichos.slice(0, 3).flatMap(n =>
  (n.articulos_ideas || []).slice(0,2).map(idea => `• ${n.nombre}: ${idea}`)
).join('<br>');

return [{
  json: {
    to: 'kromasoldeluis@gmail.com',
    subject: `🏭 Fábrica de Blogs — Resumen Semanal ${new Date().toLocaleDateString('es-MX')}`,
    htmlBody: `
<h2>🏭 Fábrica Autónoma de Blogs — Reporte Semanal</h2>
<p>Se han generado y publicado artículos automáticamente en todos los blogs activos esta semana.</p>

<h3>🔍 Top 5 Nichos Recomendados para Nuevos Blogs</h3>
<p>${topNichos}</p>

<h3>💡 Ideas de Artículos para Nichos Nuevos</h3>
<p>${articulosIdeas}</p>

<h3>✅ Próximos Pasos</h3>
<ul>
  <li>Revisa la pestaña <b>"Nichos Recomendados"</b> en Google Sheets para el análisis completo</li>
  <li>Revisa <b>"Fabrica Log"</b> para ver todos los artículos publicados esta semana</li>
  <li>Considera crear nuevos blogs en Blogger para los nichos con mayor potencial</li>
</ul>

<p style="color:#aaa;font-size:12px">Generado automáticamente por n8n + DeepSeek AI · ${new Date().toISOString()}</p>
`
  }
}];
